import { selectAuthToken } from '../../../user/slice';

import * as actions from '../actions';

import { Message } from '../types';
import { Thunk } from '../../../../types.global';

const requestFriends = async (method: 'POST' | 'PATCH' | 'GET' | 'DELETE', state, data, query = '') => {
  const authorization = selectAuthToken(state);
  const res = await fetch(`${process.env.APP_URL}/api/friends${query}`, {
    method,
    headers: {
      ...(authorization && { authorization }),
      'Content-Type': 'application/json',
    },
    ...(data && { body: JSON.stringify(data) }),
  });

  if (!res.ok) {
    console.error('requestFriends', res);
    const content = await res[res.status === 422 ? 'json' : 'text']();
    return Promise.reject({ statusCode: res.status, content });
  }

  return res.json();
};

export const sendMessage = (data: any): Thunk => (dispatch, getState) => {
  dispatch(actions.sendMessage.pending());
  const state = getState();

  return requestFriends('POST', state, data)
    .then((result) => {
      dispatch(actions.sendMessage.fulfilled(result));
      // const userId = state.user?.loggedUser?.value?.id;
      // peer
      //   .send(data.friendTo, { type: 'friends/sendMessage', data: result })
      //   .catch((err) => {
      //     console.error('sendMessage', err);
      //   });
    })
    .catch((err) => {
      dispatch(actions.sendMessage.rejected(err))
    });
};

export const sawMessage = (message: Message): Thunk => (dispatch, getState) => {
  dispatch(actions.sawMessage.pending());

  const state = getState();

  return requestFriends('PATCH', state, { id: message.id })
    .then((result) => {
      dispatch(actions.sawMessage.fulfilled(result));

      // peer
      //   .send(message.friendFrom, { type: 'friends/sawMessage', data: result })
      //   .catch((err) => {
      //     console.error('sendMessage', err);
      //   });
    })
    .catch((err) => {
      console.error('requestFriends', err);
      dispatch(actions.sawMessage.rejected(err))
    });
};

export const deleteFriend = (friendTo: string): Thunk => async (dispatch, getState) => {
  const result = await requestFriends('DELETE', getState(), {
    friendTo,
  });
  dispatch(actions.deletedFriend(result));
  return result;
};
